mapper.select:
SELECT uf.id, uf.user_id, uf.product_id, uf.is_deleted, uf.create_time, uf.update_time, uf.delete_time, u.nickname as userName, p.name as productName, p.images as productImages, p.price as productPrice FROM user_favorite uf LEFT JOIN user u ON uf.user_id = u.id LEFT JOIN product p ON uf.product_id = p.id
uf.is_deleted = 0
AND uf.user_id = #{queryParams.userId}
AND uf.product_id = #{queryParams.productId}
AND u.nickname LIKE CONCAT('%', #{queryParams.userName}, '%')
AND p.name LIKE CONCAT('%', #{queryParams.productName}, '%')
AND uf.create_time >= #{queryParams.createTime[0]}
AND uf.create_time <= #{queryParams.createTime[1]}
ORDER BY uf.create_time DESC
